export function AgendaView({
  title = "{{title}}",
  rows = "{{rows}}",
  density = "{{density}}",
  showTime = {{showTime}},
  accent = "{{accent}}",
}) {
  const events = [
    { time: "9:00 am", iso: "2026-08-18T09:00", label: "Team standup" },
    { time: "11:30 am", iso: "2026-08-18T11:30", label: "Design review" },
    { time: "2:00 pm", iso: "2026-08-18T14:00", label: "Client call" },
    { time: "4:30 pm", iso: "2026-08-18T16:30", label: "Wrap-up notes" },
  ].slice(0, Number(rows));
  const pad = density === "Compact" ? "4px 0" : "10px 0";
  return (
    <section style={{ font: "15px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 420, padding: 20, borderRadius: 14, boxSizing: "border-box" }}>
      <h2 style={{ margin: "0 0 12px", fontSize: 17, fontWeight: 700 }}>{title}</h2>
      <ol style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {events.map((e) => (
          <li key={e.label} style={{ display: "flex", alignItems: "baseline", gap: 14, padding: pad, borderLeft: `3px solid ${accent}`, paddingLeft: 12, marginBottom: density === "Compact" ? 2 : 6 }}>
            {showTime && <time dateTime={e.iso} style={{ flex: "0 0 auto", fontVariantNumeric: "tabular-nums", color: "#24143099", fontSize: 13, width: 62 }}>{e.time}</time>}
            <span style={{ fontWeight: 600 }}>{e.label}</span>
          </li>
        ))}
      </ol>
    </section>
  );
}
